def dependencies(
    requested: tuple[str, ...], *, retained: Mapping[str, Sequence[str]] | None = None
) -> dict[str, set[str]]:
    """Use pinned consumed inputs for reused answers; fresh work keeps catalog requirements.

    This only plans reuse. The caller must still verify the retained bytes,
    source/upstream hashes and analytical scope before consuming any answer.
    """
    catalog = {module.module_id: module for module in modules()}
    fixed = {module_id: set(inputs) for module_id, inputs in (retained or {}).items()}
    if fixed.keys() - catalog.keys() or any(inputs - catalog.keys() for inputs in fixed.values()):
        raise ValueError("Unknown canonical retained module dependency")
    selected = {canonical(entry) for entry in requested}
    pending = list(selected)
    while pending:
        module_id = pending.pop()
        for dependency in fixed.get(module_id, catalog[module_id].required):
            if dependency not in selected:
                selected.add(dependency)
                pending.append(dependency)

    # Optional dependencies constrain execution only when selected.
    remaining = {
        module_id: set(fixed.get(module_id, catalog[module_id].required))
        | (set(catalog[module_id].optional) & selected)
        for module_id in selected
    }
    if "CP-5" in selected:
        # QA follows every selected analyst except CP-MODEL (a stop in the owner walk, D12);
        # challenge and exports follow QA.
        remaining["CP-5"] |= selected - _NOT_CP5_FAN_IN

    return remaining
